const workerCanNotify = (r: { showNotification?: unknown; getNotifications?: unknown }) =>
  typeof r.showNotification === 'function' && typeof r.getNotifications === 'function';

export async function notify(title: string, opts: NotificationOptions, open: () => void) {
  if (typeof Notification === 'undefined' || Notification.permission !== 'granted') return; // iOS tab: Notification is undefined
  const reg = await navigator.serviceWorker?.getRegistration();
  if (reg && workerCanNotify(reg)) return reg.showNotification(title, opts);
  const n = new Notification(title, opts); // desktop tab / no worker yet
  n.onclick = () => { window.focus(); open(); n.close(); };
}

type RichOptions = NotificationOptions & { renotify?: boolean; image?: string; timestamp?: number; actions?: { action: string; title: string }[] };
