export async function closeFor(code: string, ch: string, unread: number) {
  const reg = await navigator.serviceWorker?.getRegistration();
  if (reg && typeof reg.getNotifications === 'function') {
    for (const n of await reg.getNotifications()) {
      const d = noticeDataOf(n.data);
      if (d?.code === code && d.ch === ch) n.close();
    }
  }
  const badge = unread ? navigator.setAppBadge?.(unread) : navigator.clearAppBadge?.();
  badge?.catch(() => { /* not installed: no icon to badge */ });
}

